def minify(s: str) -> str:
    """Map a short lowercase token to a shorter lowercase token (used for log keys)."""
    if not s:
        return ""
    hash_value = sum(ord(c) for c in s) % 26
    return string.ascii_lowercase[hash_value] if len(s) > 0 else ""

